import { loadJSON } from './data-loader.js';
import { initLocale, getLocale } from './i18n.js';
await initLocale();
import { meaningfulPowers, ratingForSeat } from './seat-outlook.js';
import { comparisonHTML } from './seat-comparison.js';
import { createParliament } from './parliament.js';
let theatre=null,profileData=[],powersData=null,leadershipData=null,selectedPower='ordinary_passage';
const $=s=>document.querySelector(s), esc=s=>String(typeof s==='number'?new Intl.NumberFormat(getLocale(),{useGrouping:false}).format(s):(s??'')).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,evidence,chamber='senate',scene,camera,renderer,group,meshes=[],selected;
const colors={D:0x155dff,R:0xf1264f,I:0x9c54ff,U:0x7c8999,T:0xf8b82b},names={D:'民主党',R:'共和党',I:'独立',U:'待核验',T:'竞争胶着'};
const ratingLabel=r=>r?.ratingZh||({'solid-D':'民主党稳固','likely-D':'民主党优势','lean-D':'倾向民主党','tossup':'竞争胶着','lean-R':'倾向共和党','likely-R':'共和党优势','solid-R':'共和党稳固'}[r?.rating])||'暂无核验评级';
function rate(s){return ratingForSeat(s,evidence);}
function party(s){if(!s.contested2026)return s.currentParty||'U';let r=rate(s);return r?.rating==='tossup'?'T':r?.party||r?.leanParty||(String(r?.rating||'').endsWith('D')?'D':String(r?.rating||'').endsWith('R')?'R':'U');}
function label(s){return s.chamber==='senate'?`${s.state} · 参议院${s.special?'特别选举':''}`:`${s.state}-${s.district===0?'AL':String(s.district).padStart(2,'0')}`;}
function show(s){selected=s;$('#seat-title').textContent=label(s);const r=rate(s);$('#seat-detail').innerHTML=`<strong>${esc(s.incumbent||'现任空缺')}</strong><br>现任：${esc(names[s.currentParty]||'空缺')} ${s.caucus&&s.caucus!==s.currentParty?`（${names[s.caucus]}党团）`:''}<br>${s.contested2026?'2026 改选':'本届不改选'}${s.contested2026?`<br>机构评级：${esc(ratingLabel(r))}`:''}${s.chamber==='house'?'<br><span class="small muted">现任为第119届记录；2026评级按新选举区，不代表现任参选或选区边界不变。</span>':''}<br><a href="${esc(r?.source||s.source)}" target="_blank" rel="noopener">原始来源 ↗</a>`;}
function table(){let q=$('#seat-search').value.toLowerCase();$('#seat-table').innerHTML=data.seats.filter(s=>s.chamber===chamber&&JSON.stringify([s.seatId,s.incumbent,s.state]).toLowerCase().includes(q)).map(s=>`<div class="seat-row"><button data-seat="${s.seatId}">${esc(label(s))} · ${esc(s.incumbent||'空缺')}</button><span>${s.contested2026?esc(ratingLabel(rate(s))):esc(names[s.currentParty])+' · 不改选'}</span></div>`).join('');document.querySelectorAll('[data-seat]').forEach(b=>b.onclick=()=>{let seat=data.seats.find(s=>s.seatId===b.dataset.seat);show(seat);theatre?.focus(seat);openProfile(seat);});}
function init3D(){try{theatre=createParliament($('#canvas'),{seats:data.seats,party,rate,label,onSelect:s=>{show(s);openProfile(s);},changes:evidence.ratingChanges,leadership:leadershipData,onLeader:showLeader});sceneStats();table();}catch(e){$('#canvas').dataset.renderError=e.message;fallback();table();document.querySelectorAll('.scene-controls button').forEach(b=>b.disabled=true);$('.model-caption').textContent='2D 兼容模式 / 当前浏览器未启用 WebGL';$('#scene-status').textContent='3D 相机功能需浏览器支持 WebGL';}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));theatre?.setMode(b.dataset.view);$('#scene-status').textContent=b.dataset.view==='current'?'现任党籍配色 · 不改变实际/示意座位':b.dataset.view==='changes'?'来源已记录评级变更的席位以金色光环标记':'公开机构评级配色 · 非本站胜率';});$('#scene-reset').onclick=()=>theatre?.reset();$('#scene-front').onclick=()=>theatre?.front();$('#scene-left').onclick=()=>theatre?.orbit(-Math.PI/6);$('#scene-right').onclick=()=>theatre?.orbit(Math.PI/6);$('#scene-top').onclick=()=>theatre?.top();$('#scene-zoom-in').onclick=()=>theatre?.zoom(.8);$('#scene-zoom-out').onclick=()=>theatre?.zoom(1.25);}
function sceneStats(){renderPowers();renderLeadership();let ct=data.counts[chamber];$('#chamber-stats').innerHTML=`<div class="statline"><span>全部席位</span><strong>${ct.total}</strong></div><div class="statline"><span>本届改选</span><strong>${ct.contested2026}</strong></div><div class="statline"><span>多数门槛</span><strong>${chamber==='senate'?'51*':'218'}</strong></div><p class="small muted">${chamber==='senate'?'*50–50时由副总统投关键票。':'现任选区不等于2026选举区；新候选人分别核验。'}</p>`;}
function fill(){let d=new Date(evidence.asOf||data.asOf);$('#asof').textContent=d.toLocaleString(getLocale(),{timeZone:'Asia/Tokyo',hour12:false})+' JST';$('#summary').innerHTML=[['当前参院党团','53 R / 47 D','含 2 名独立议员加入民主党党团'],['本届改选','35 / 435','参议院 / 众议院；含参院 2 席特别选举'],['时间序列','首版基线','缺席位历史，不推算单日胜率']].map(x=>`<article class="summary-card"><div class="eyebrow">${x[0]}</div><div class="big">${x[1]}</div><div class="small muted">${x[2]}</div></article>`).join('');const watch=['MI','OH','ME','AK','TX','IA','NC','GA','NH'];let ratings=(evidence.ratings||[]).filter(x=>x.chamber==='senate'&&watch.includes(x.state));$('#ratings').innerHTML=ratings.length?ratings.map((r,i)=>`<article class="rating-card"><div class="rating-meta"><span>${String(i+1).padStart(2,'0')} / ${esc(r.state)} SENATE</span><span>${esc(r.provider||'公开机构评级')}</span></div><h3>${esc(r.state)} <span class="muted">${esc(ratingLabel(r))}</span></h3><div class="rating-band"></div><p>${esc(r.note||'当前机构评级快照；已核验的历史变更见下方事件列表，不计算虚构胜率涨跌。')}</p><a class="small" target="_blank" rel="noopener" href="${esc(r.source)}">评级原文 ↗</a></article>`).join(''):'<div class="trend-blank">尚无足够的同口径评级历史，暂不生成变化排名。</div>';
let history=evidence.history||[];$('#trend').innerHTML=history.length?history.map(h=>`<div class="trend-row"><div>${esc(h.date||h.asOf)}<div class="small muted">${esc(h.metric||h.label||'泛国会投票意向')} · ${'RCP'}</div></div><strong>${esc(h.display|| (h.margin!=null?'D+'+h.margin:'待核验'))}</strong></div><p class="small muted">${esc(h.note)}</p>`).join(''):'<div class="trend-blank">尚无完整的连续日线。<br>从本次已核验快照建立基线，不回填虚构历史。</div>';
$('#news').innerHTML=(evidence.news||[]).map(n=>`<article class="news-item"><small>${esc(n.date)} / ${esc(n.type||'公开报道')}</small><a href="${esc(n.url||n.source)}" target="_blank" rel="noopener">${esc(n.title)} ↗</a><p>${esc([n.summary,n.status,n.interpretation].filter(Boolean).join(' '))}</p></article>`).join('')||'<p class="muted">暂未录入完成核验的新闻条目。</p>';
const ms=[['事实与预测分层','现任归属来自国会官方名单。改选席位的颜色只表示标注机构的公开评级，既非结果，也非本站独立胜率。'],['缺数据，不补故事','灰色表示评级未知；没有同口径历史时不声称评级变化。单日民调和滚动均值变化不能被当作结构性转折。'],['民调与误差','优先高质量可能投票者样本。历史误差情景需可比原始输入；未经校准的敏感性修正不称为真实支持率，也不机械复制 2024 年误差。'],['投票与管理事件','提前投票党派登记不等于得票。诉讼申请、法院裁定与实际执行分开标注。参考来源可复核，结论随新证据修订。']];$('#methods').innerHTML=(evidence.methodology||ms.map(x=>({title:x[0],text:x[1]}))).map(x=>`<div class="method-item"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></div>`).join('');let ss=[...(data.sources||[]),...(evidence.sources||[])];let seen=new Set;$('#sources').innerHTML=ss.filter(x=>!seen.has(x.url)&&seen.add(x.url)).map(s=>`<div class="source"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title||s.description||s.name||s.url)} ↗</a><small>${esc(s.sourceDate||s.date||'来源日期见原文')} · 获取于 ${esc((evidence.asOf||data.asOf).slice(0,10))}</small></div>`).join('');}
Promise.all([loadJSON('data/seats.json'),loadJSON('data/evidence.json'),loadJSON('data/powers.json'),loadJSON('data/leadership.json')]).then(([s,e,p,l])=>{data=s;evidence=e;powersData=p;leadershipData=l;fill();extras();renderPowers();renderLeadership();init3D();document.querySelectorAll('[data-chamber]').forEach(b=>b.onclick=()=>{chamber=b.dataset.chamber;document.querySelectorAll('[data-chamber]').forEach(x=>x.classList.toggle('active',x===b));theatre?theatre.update(chamber):fallback();sceneStats();table();$('#seat-title').textContent='选择一个席位';$('#seat-detail').textContent='点击模型或使用下方列表，查看具体席位。';});$('#seat-search').oninput=table;}).catch(()=>{$('#asof').textContent='数据暂时无法读取';$('#canvas').innerHTML='<p class="trend-blank">数据加载失败，请稍后刷新。此状态不代表没有选举变化。</p>';});

function extras(){
const ratingText=r=>ratingLabel({rating:r});
const changes=document.createElement('div');changes.className='change-events';changes.innerHTML='<h3>已核验的机构评级变更</h3><p class="small muted">以下为 RCP 变更日志日期，不是本站每日预测。事件按时间倒序，不按虚构胜率排序。</p>'+(evidence.ratingChanges||[]).map(c=>`<a class="event-row" href="${esc(c.source)}" target="_blank" rel="noopener"><span>${esc(c.date)}</span><strong>${esc(c.state)}</strong><span>${esc(ratingText(c.before))} → ${esc(ratingText(c.after))}</span><span>↗</span></a>`).join('');$('#changes').appendChild(changes);
const summary=evidence.summary;$('#summary').innerHTML=[['RCP 参院评级总览',`${summary.senate.dem} D · ${summary.senate.tossup} 胶着 · ${summary.senate.rep} R`,'含65个不改选席；D阵营含2名独立议员'],['RCP 众院评级总览',`${summary.house.dem} D · ${summary.house.tossup} 胶着 · ${summary.house.rep} R`,'完整机构总览；不等于逐席均已映射'],['逐席评级覆盖',`${evidence.coverage.senateRatings} / ${data.counts.senate.contested2026} · ${evidence.coverage.houseRatings} / 435`,`参院改选 / 众院；众院${evidence.coverage.houseUnmappedSolid}席待逐席核验`]].map(x=>`<article class="summary-card"><div class="eyebrow">${x[0]}</div><div class="big" style="font-size:23px">${x[1]}</div><div class="small muted">${x[2]}</div></article>`).join('');
const polls=document.createElement('section');polls.innerHTML='<div class="section-top"><div><p class="eyebrow">POLLING / ORIGINAL SAMPLES</p><h2>关键原始民调</h2></div><span class="tag">不与机构评级混算</span></div><div class="ratings-grid">'+(evidence.polls||[]).map(p=>`<article class="rating-card"><div class="rating-meta">${esc(p.pollster)} / ${esc(p.state)}</div><h3>${p.dem}% D · ${p.rep}% R</h3><p>调查 ${esc(p.fieldStart)} 至 ${esc(p.fieldEnd)}<br>样本 ${p.sample} · ${esc(p.sampleType)}<br>误差 ±${p.moe} 个百分点</p><p class="muted">${esc(p.mode)}。权重：${esc(p.weighting)}。${esc(p.note)}</p><a class="small" href="${esc(p.source)}" target="_blank" rel="noopener">原始民调 ↗</a></article>`).join('')+'</div>';$('#evidence').before(polls);
const limits=document.createElement('p');limits.className='small muted';limits.textContent='覆盖限制：'+evidence.coverage.limitations.join(' ');$('.source-section').prepend(limits);
let hs=evidence.history.slice(-14); if(hs.length>1){let step=380/(hs.length-1),lo=Math.min(...hs.map(h=>h.margin))-.2,hi=Math.max(...hs.map(h=>h.margin))+.2,yy=h=>100-(h.margin-lo)/(hi-lo)*75;let points=hs.map((h,i)=>`${40+i*step},${yy(h)}`).join(' ');let svg=`<svg viewBox="0 0 460 145" role="img" aria-label="RCP全国泛国会票领先差快照，详细数值见下方记录"><path d="M40 110H420" stroke="#e0e5dc"/><polyline points="${points}" fill="none" stroke="#3985b0" stroke-width="2"/>${hs.map((h,i)=>`<circle cx="${40+i*step}" cy="${yy(h)}" r="4" fill="#3985b0"/><text x="${40+i*step}" y="${yy(h)-15}" text-anchor="middle" font-size="13" fill="#3985b0">D+${h.margin}</text><text x="${40+i*step}" y="133" text-anchor="middle" font-size="10" fill="#71807b">${h.date.slice(5)}</text>`).join('')}</svg><p class="small muted">票差单位：百分点。纵轴为局部范围，点间线仅辅助读取；非席位趋势。</p>`;$('#trend').insertAdjacentHTML('afterbegin',svg);}
}

function fallback(){
const ss=data.seats.filter(s=>s.chamber===chamber).sort((a,b)=>(chamber==='senate'?Number(b.contested2026)-Number(a.contested2026):0)||({D:0,I:1,T:2,U:3,R:4}[a.currentParty||'U']-{D:0,I:1,T:2,U:3,R:4}[b.currentParty||'U'])||a.seatId.localeCompare(b.seatId));const rows=chamber==='senate'?[16,19,30,35]:[25,29,33,37,41,45,49,53,59,64];let ps=[];rows.forEach((n,k)=>{let r=chamber==='senate'?[105,140,220,255][k]:110+k*21;for(let j=0;j<n;j++){let a=Math.PI*j/(n-1);ps.push({x:400-Math.cos(a)*r,y:330-Math.sin(a)*r*.85,a,row:k});}});ps.sort((a,b)=>(chamber==='senate'?Number(a.row>=2)-Number(b.row>=2):0)||a.a-b.a||a.y-b.y);let w=chamber==='senate'?23:12;$('#canvas').innerHTML=`<svg viewBox="0 0 800 400" role="img" aria-label="无WebGL设备使用同数据交互议席示意图" style="width:100%;height:100%">${chamber==='senate'?'<path d="M220 330 A180 153 0 0 1 580 330" fill="none" stroke="#b7a16e" stroke-width="13" opacity=".6"/>':''}<path d="M338 330 A62 48 0 0 1 462 330 L462 339 L338 339Z" fill="#e9eee5"/>${ss.map((s,i)=>{let p=ps[i],c='#'+colors[party(s)].toString(16);return `<g class="svg-seat" data-svg-seat="${s.seatId}" tabindex="0" role="button" aria-label="${esc(label(s))} ${s.contested2026?esc(ratingLabel(rate(s))):'不改选'}"><rect x="${p.x-w/2}" y="${p.y-w/3+4}" width="${w}" height="${w*.75}" rx="2" fill="${c}" opacity="${s.contested2026?.08:.25}"/><rect x="${p.x-w/2}" y="${p.y-w/3}" width="${w}" height="${w*.75}" rx="2" fill="${s.contested2026?'white':c}" stroke="${c}" stroke-width="1.5" stroke-opacity="${chamber==='house'?.3:1}" ${s.contested2026?'stroke-dasharray="3 2"':''}/><path d="M${p.x-w/2},${p.y-w/3}h${w}" stroke="${c}" stroke-width="3" opacity=".6"/></g>`}).join('')}<text x="400" y="383" font-size="10" text-anchor="middle" fill="#87958b">2D 兼容模式 · 相同数据，可点击查看席位</text></svg>`;document.querySelectorAll('[data-svg-seat]').forEach(el=>{const fn=()=>{let seat=ss.find(s=>s.seatId===el.dataset.svgSeat);show(seat);openProfile(seat);};el.onclick=fn;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')fn();};});let ct=data.counts[chamber];$('#chamber-stats').innerHTML=`<div class="statline"><span>全部席位</span><strong>${ct.total}</strong></div><div class="statline"><span>本届改选</span><strong>${ct.contested2026}</strong></div><div class="statline"><span>多数门槛</span><strong>${chamber==='senate'?'51*':'218'}</strong></div><p class="small muted">${chamber==='senate'?'* 50–50 时由副总统投关键票；党团归属与登记党籍分开。':'现任选区记录不等于2026候选人表；部分州区划已改变。'}</p>`;
}

async function loadProfiles(){for(const f of ['senate_profiles','house_profiles']){try{const j=await loadJSON('data/'+f+'.json');profileData.push(...j.profiles.map(p=>({...p,profileAsOf:j.asOf})));}catch{}}}loadProfiles();
function openProfile(s){let p=profileData.find(x=>x.seatId===s.seatId),panel=$('#profile-drawer');let inc=p?.incumbent||{};const photo=(inc.photo||inc.portrait)?.usageAllowed?(inc.photo||inc.portrait):null,initials=(inc.name||s.incumbent||'空缺').split(/[ ,]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('');const sourcedList=items=>(items||[]).map(x=>`<li>${esc(typeof x==='string'?x:x.text||x.title)}${x.attribution?` <small>（${esc(x.attribution)}）</small>`:''}${x.source?` <a href="${esc(x.source)}" target="_blank" rel="noopener">来源↗</a>`:''}</li>`).join('');$('#profile-body').innerHTML=`<p class="eyebrow">${esc(label(s))} / ${s.contested2026?'2026竞选席位':'不改选席位'}</p><section class="person-id"><div class="person-portrait">${photo?`<img src="${esc(photo.url)}" alt="${esc(inc.name)} 官方肖像">`:`<span>${esc(initials)}</span><small>官方头像待核验</small>`}</div><div><span class="eyebrow">PUBLIC SERVICE ID</span><h2>${esc(inc.name||s.incumbent||'现任空缺')}</h2><span class="profile-badge">现任 · ${esc(names[s.currentParty]||'空缺')}</span></div></section>${photo?`<p class="small muted">头像：${esc(photo.credit||photo.attribution||'官方公开肖像')} · <a href="${esc(photo.rightsSource||photo.source)}" target="_blank" rel="noopener">来源与使用依据 ↗</a></p>`:''}<p>${esc(inc.role||(s.vacant?'该席现任空缺':s.chamber==='senate'?'美国联邦参议员':'第119届美国联邦众议员'))}</p><div class="honors-strip"><strong>荣誉记录</strong>${inc.honors?.length?`<ul>${sourcedList(inc.honors)}</ul>`:'<span>尚待核验，不代表没有荣誉</span>'}</div><h3>履历与背景</h3><p>${esc(inc.background||'个人背景尚待逐项核验；请查看国会官方资料。未将推测填入个人履历。')}</p><a href="${esc(inc.source||s.source)}" target="_blank" rel="noopener">官方/原始个人资料 ↗</a>${inc.backgroundSource&&inc.backgroundSource!==inc.source?` · <a href="${esc(inc.backgroundSource)}" target="_blank" rel="noopener">履历依据 ↗</a>`:''}<section class="record-card"><h3>政策主张与主要工作</h3><h4>历史主张</h4>${((inc.positions?.length?inc.positions:inc.policyPositions))?.length?`<ul>${sourcedList((inc.positions?.length?inc.positions:inc.policyPositions))}</ul>`:'<p class="small muted">尚未取得逐项核验的政策记录，不以党派标签推断个人主张。</p>'}<h4>主要成就 / 立法工作</h4>${((inc.accomplishments?.length?inc.accomplishments:inc.majorAchievements?.length?inc.majorAchievements:inc.achievements))?.length?`<ul>${sourcedList((inc.accomplishments?.length?inc.accomplishments:inc.majorAchievements?.length?inc.majorAchievements:inc.achievements))}</ul>`:'<p class="small muted">待以法案、国会记录及独立资料核验；不将竞选宣传直接当作既定成就。</p>'}</section>${s.contested2026?'<div class="divider"></div><h3>2026 主要竞争者</h3><p class="small muted">候选人按已核验资料展示，不按未验证的胜率排名。民调得票支持率不等于预测得票率或当选概率。</p>':''}${(p?.candidates||[]).map(c=>`<article class="candidate-card party-${esc(c.party)}"><div><h3>${esc(c.name)}</h3><span class="profile-badge">${esc(names[c.party]||c.party||'党籍待核验')}</span></div><p>${esc(c.background||'履历待核验')}</p><a href="${esc(c.source)}" target="_blank" rel="noopener">背景来源 ↗</a>${(c.polls||[]).map(q=>`<div class="candidate-poll"><strong>${q.share==null?'—':esc(q.share)+'%'}</strong><div>${esc(q.pollster)} · 原始民调<br><small>${esc(q.fieldStart)}—${esc(q.fieldEnd)} · ${esc(q.sampleType||'样本见来源')}</small><br><a href="${esc(q.source)}" target="_blank" rel="noopener">调查原文 ↗</a></div></div><details class="poll-method"><summary>调查方法与限制</summary><p>${esc(q.note||'')}</p><p>样本：${esc(q.sample||'见来源')}；模式：${esc(q.mode||'见来源')}；权重：${esc(q.weighting||'见来源')}；误差：${q.moe==null?'见来源':'±'+esc(q.moe)+'个百分点'}</p></details>`).join('')||'<p class="small muted">暂无可核验、可对应此候选人的近期民调。</p>'}</article>`).join('')}${s.contested2026&&!(p?.candidates?.length)?'<p class="muted">此席主要竞争者资料仍待核验，暂不展示推测名单。</p>':''}${s.contested2026?'<div class="forecast-note"><strong>模型预测得票率：暂无可靠输出</strong><p>不将定性评级或原始民调百分比冒充模型预测，也不生成虚构当选概率。</p></div>':''}<p class="small muted">资料截至 ${esc(p?.profileAsOf||'待核验')}<br>${esc(p?.note||'现任资料与竞选资料分开。众院现任为第119届记录，2026区划与竞选人需独立核验。')}</p>`;const portraitImg=panel.querySelector('.person-portrait img');if(portraitImg)portraitImg.onerror=()=>{portraitImg.parentElement.innerHTML=`<span>${esc(initials)}</span><small>头像暂无法加载</small>`;};panel.classList.add('open');$('#profile-scrim').hidden=false;$('#profile-close').focus();}
function closeProfile(){$('#profile-drawer').classList.remove('open');$('#profile-scrim').hidden=true;}$('#profile-close').onclick=closeProfile;$('#profile-scrim').onclick=closeProfile;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile();});

document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!$('#profile-drawer').classList.contains('open'))return;const fs=[...$('#profile-drawer').querySelectorAll('button,a[href],input')];const first=fs[0],last=fs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});

function renderPowers(){$('#seat-zones').innerHTML=chamber==='senate'?'<span>前区 · 本届改选 35</span><span>金色宽过道分隔</span><span>后区 · 本届不改选 65</span>':'<span>众议院 435 席 · 本届全部改选</span><span>无不改选保留区 · 点击席位聚焦</span>';if(!powersData)return;let ids=meaningfulPowers(powersData,chamber).map(p=>p.id);$('#power-panel').innerHTML=`<div class="power-heading"><div><span class="eyebrow">POWER & PROCEDURE</span><h3>席位分布与权力门槛</h3></div></div><div class="power-segments" data-count="${ids.length}" role="tablist" aria-label="选择议会程序">${ids.map(id=>{let p=powersData.powers.find(x=>x.id===id);return `<button role="tab" id="power-tab-${id}" data-power="${id}" aria-selected="${id===selectedPower}" aria-controls="power-content" tabindex="${id===selectedPower?0:-1}" title="${esc(p.labelZh)}">${powerIcon(id)}<span>${esc(powerShort(id))}</span></button>`;}).join('')}</div><div id="power-content" role="tabpanel"></div>`;const tabs=[...document.querySelectorAll('[data-power]')];if(!ids.includes(selectedPower))selectedPower='ordinary_passage';const choose=(id,focus=false)=>{selectedPower=id;tabs.forEach(b=>{let active=b.dataset.power===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus)b.focus();});renderPowerContent();};tabs.forEach((b,i)=>{b.onclick=()=>choose(b.dataset.power);b.onkeydown=e=>{let next=e.key==='ArrowRight'?(i+1)%tabs.length:e.key==='ArrowLeft'?(i+tabs.length-1)%tabs.length:e.key==='Home'?0:e.key==='End'?tabs.length-1:null;if(next!==null){e.preventDefault();choose(tabs[next].dataset.power,true);}};});choose(selectedPower); }
let thresholdSide='D';
function renderPowerContent(){const p=powersData.powers.find(x=>x.id===selectedPower);$('#power-content').setAttribute('aria-labelledby','power-tab-'+selectedPower);$('#power-content').innerHTML=comparisonHTML(data,evidence,chamber,p,esc,thresholdSide)+`<details class="power-rule"><summary>${esc(p.labelZh)} · ${esc(p.shortLabelZh)}</summary><p>${esc(p.rule)}</p><p class="small muted">${esc((p.caveats||[]).join(' '))}</p><p class="small">${p.source.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)} ↗</a>`).join(' · ')}</p></details><details class="power-rule"><summary>基础程序与来源</summary>${powersData.powers.filter(x=>!x.gauge?.showSeatLine).map(x=>`<p><strong>${esc(x.labelZh)}</strong> · ${esc(x.rule)}</p><p>${x.source.map(y=>`<a href="${esc(y.url)}" target="_blank" rel="noopener">${esc(y.title)} ↗</a>`).join(' · ')}</p>`).join('')}</details><p class="small muted">党派席位不是实际赞成票；跨党投票、出席、程序及总统阶段均影响结果。无统一“重大议案”门槛。核验于 ${esc(powersData.verifiedAt)}。</p>`;document.querySelectorAll('[data-threshold-side]').forEach(b=>b.onclick=()=>{thresholdSide=b.dataset.thresholdSide;renderPowerContent();});}
function renderLeadership(){if(!leadershipData)return;let c=leadershipData[chamber],items=[c.podium,...(c.scenarios||c.partyLeadershipScenarios||[])];$('#leadership-panel').innerHTML=`<p class="eyebrow">PRESIDING OFFICER & CONDITIONAL SCENARIOS</p><div class="leader-grid">${items.map((x,i)=>{let p=leadershipData.persons.find(p=>p.id===x.personId);return `<button class="leader-card ${i?'conditional':''}" data-leader="${i}"><small>${esc(x.label)}</small><strong>${esc((getLocale()==='zh-CN'?p.nameZh:p.name))}</strong><span>${i?'虚线：条件情景，尚未当选':esc(p.currentRole)}</span></button>`;}).join('')}</div><p class="small muted">${esc(c.notes[0])} 点击讲台人偶或姓名查看条件与原始依据。</p>`;$('#leadership-panel').querySelectorAll('[data-leader]').forEach(b=>b.onclick=()=>showLeader(items[Number(b.dataset.leader)]));}
function showLeader(entry){let p=leadershipData.persons.find(p=>p.id===entry.personId);$('#profile-body').innerHTML=`<p class="eyebrow">${entry.render==='dashed'?'条件情景 / 不是选举结果':'已核验现任职务'}</p><section class="person-id"><div class="person-portrait"><span>${esc(p.name.split(' ').map(x=>x[0]).join(''))}</span></div><div><h2>${esc((getLocale()==='zh-CN'?p.nameZh:p.name))}</h2><p>${esc(p.name)}</p><span class="profile-badge">${esc(names[p.party])}</span></div></section><h3>${esc(entry.label)}</h3><p>${esc(p.currentRole)}</p><p>${esc(entry.condition||entry.note||'现任职务示意，不表示此刻正在主持会议。')}</p><p>${esc(entry.possibleRole||'')}</p><a href="${esc(entry.source||p.source)}" target="_blank" rel="noopener">官方与情景依据 ↗</a><p class="small muted">人偶为抽象示意，不模拟本人相貌。不提供人选胜率。资料截至 ${esc(leadershipData.asOf)}。</p>`;$('#profile-drawer').classList.add('open');$('#profile-scrim').hidden=false;$('#profile-close').focus();}

const powerSymbols={bill_introduction:'M6 3h12v18H6z M9 8h6 M12 5v6 M9 15h6',ordinary_passage:'M4 12l5 5L20 6',speaker_election:'M5 19h14 M7 19v-6h10v6 M12 4v6 M9 7h6',legislative_cloture:'M5 5h14v11H9l-4 4z M9 9h6 M9 12h4',reconciliation:'M4 6h16v14H4z M8 3v6 M16 3v6 M8 13h8 M8 16h5',nominations:'M12 3a4 4 0 1 0 0 8a4 4 0 1 0 0-8 M5 21v-3a7 7 0 0 1 14 0v3',veto_override:'M7 8h10a5 5 0 0 1 0 10H9 M7 4L3 8l4 4',impeachment_house:'M4 20h16 M7 16V9 M12 16V9 M17 16V9 M3 7l9-4 9 4z',impeachment_conviction:'M5 20h10 M12 4l7 7 M9 7l7 7 M6 17l8-8',treaty_consent:'M3 7l6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 4v15 M15 7v15',constitutional_amendment:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h3',house_suspension:'M5 4v16 M10 4v16 M15 8l6 4-6 4z'};
function powerIcon(id){return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${powerSymbols[id]||powerSymbols.ordinary_passage}"/></svg>`;}
function powerShort(id){const labels={zh:['提交法案','最终通过','议长选举','终结辩论','预算协调','提名确认','否决覆议','弹劾指控','弹劾定罪','条约批准','宪法修正','快速程序'],en:['Introduce','Passage','Speaker','End debate','Reconciliation','Confirm','Override veto','Impeach','Convict','Treaties','Amendment','Fast-track'],fr:['Déposer','Adoption','Présidence','Clôture','Budget','Confirmer','Passer le veto','Mise en accusation','Condamner','Traités','Amendement','Procédure rapide'],es:['Presentar','Aprobar','Presidencia','Cerrar debate','Presupuesto','Confirmar','Superar veto','Acusar','Condenar','Tratados','Enmienda','Vía rápida'],ja:['法案提出','最終可決','議長選出','討論終結','予算調整','指名承認','拒否権覆し','弾劾訴追','弾劾有罪','条約承認','憲法修正','迅速手続']},ids=Object.keys(powerSymbols),lang=getLocale().split('-')[0];return labels[lang][ids.indexOf(id)]||id;}
window.addEventListener('localechange',()=>{if(data){renderPowers();$('#asof').textContent=new Date(evidence.asOf||data.asOf).toLocaleString(getLocale(),{timeZone:'Asia/Tokyo',hour12:false})+' JST';renderLeadership();}});
